def transform(grid):
    """Expand each isolated marker into the horizontal motif shown in the grid."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # The exemplar is the longest horizontal contiguous run of non-background
    # cells. Its middle cell is the alignment point for each isolated marker.
    exemplar = None
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == background:
                c += 1
                continue
            start = c
            while c < w and row[c] != background:
                c += 1
            run = row[start:c]
            if len(run) > 1 and (exemplar is None or len(run) > len(exemplar[2])):
                exemplar = (r, start, run)
    if exemplar is None:
        return [row[:] for row in grid]
    er, es, motif = exemplar
    anchor_col = es + len(motif) // 2

    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            # Find this 4-connected non-background component.
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            while q:
                rr, cc = q.popleft()
                component.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != background and (nr, nc) not in seen:
