def transform(grid):
    """Copy the largest non-background pattern, aligning its bbox center to each singleton marker."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != bg and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            components.append(cells)
    if not components:
        return [row[:] for row in grid]

    pattern = max(components, key=len)
    if len(pattern) <= 1:
        return [row[:] for row in grid]
    r0 = min(r for r, c in pattern)
    r1 = max(r for r, c in pattern)
    c0 = min(c for r, c in pattern)
    c1 = max(c for r, c in pattern)
    # The template's central bounding-box cell is the point aligned to markers.
    ar, ac = (r0 + r1) // 2, (c0 + c1) // 2
    pattern_set = set(pattern)
    out = [row[:] for row in grid]
    for comp in components:
        if comp is pattern or len(comp) != 1:
            continue
        mr, mc = comp[0]
        dr, dc = mr - ar, mc - ac
        for pr, pc in pattern_set:
            rr, cc = pr + dr, pc + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = grid[pr][pc]
    return out
